#!/usr/bin/env python3
"""Build matching previews and installable packages from original shared assets."""
from pathlib import Path
import json, shutil, base64, html, zipfile
R=Path(__file__).resolve().parent
css=(R/'shared/epoch.css').read_text()+'\n[hidden]{display:none!important}\n'
js=(R/'shared/epoch.js').read_text()
for dest in [R/'preview/assets',R/'wordpress/epoch/assets']:
 dest.mkdir(exist_ok=True,parents=True)
 for p in (R/'shared/assets').glob('*.svg'):shutil.copy2(p,dest/p.name)
 (dest/'epoch.css').write_text(css);(dest/'epoch.js').write_text(js)
 for p in (R/'blogger/assets').glob('*'):shutil.copy2(p,dest/p.name)
sun='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/></svg>'
toggle='<button class="ep-icon" data-epoch-toggle="" aria-label="Switch to paper theme" aria-pressed="false" hidden="hidden">'+sun+'</button>'
brand='<span class="ep-mark" aria-hidden="true">E</span><span>epoch<small>Independent Solana journal</small></span>'
hero='''<section class="ep-hero" aria-labelledby="ep-hero-title"><div><div class="ep-eyebrow"><span class="ep-dot"></span>A journal for the Solana curious</div><h1 id="ep-hero-title">The next block<br/>starts <span>here.</span></h1><p class="ep-lead">Ideas worth exploring. People worth following. A clearer view of the world being built on Solana.</p><div class="ep-actions"><a class="ep-button" href="#latest">Explore the journal <span aria-hidden="true">↗</span></a><a class="ep-text-link" href="GUIDES">New here? Start small <span aria-hidden="true">↗</span></a></div></div><div><div class="ep-cover"><div class="ep-cover-top"><span>INDEPENDENT PERSPECTIVES</span><span>EST. 2026</span></div><div class="ep-cover-bottom"><div><small>TECHNOLOGY / CULTURE / COMMUNITY</small><strong>Built one<br/>block at a time.</strong></div><span>Keep looking<br/>a little closer ↗</span></div></div><div class="ep-caption">Original artwork · a different perspective on the ecosystem</div></div></section>'''
notes='''<section class="ep-note"><div class="ep-eyebrow">The starting point</div><h2>Less noise.<br/>More understanding.</h2><p>You don’t need to know every acronym. Start with one good explanation, then follow your curiosity.</p><a class="ep-text-link" href="GUIDES">Open the beginner’s guide ↗</a></section>'''
banner='''<section class="ep-banner"><div><div class="ep-eyebrow">Good questions come first</div><h2>Stay curious. Keep your keys yours.</h2><p>Learn how wallets, permissions and transactions work before you put them to use.</p></div><a class="ep-button secondary" href="SECURITY">Explore wallet safety ↗</a></section>'''
topics=['Guides','Ecosystem','DeFi','Builders','Culture','Security']
posts=[('security','Security','The wallet check you should make before every connection','Permissions are small decisions with real consequences. Here’s how to read them without getting lost.', 'Maya Chen','MC'),('builders','Builders','Behind the build: shipping something people actually use','A field guide to listening, simplifying and finding the first useful version of an idea.','Arun Rao','AR'),('defi','DeFi','Liquidity pools, explained without the spreadsheet','What happens when two tokens share a pool—and why the price changes when someone trades.','Alex Rivera','AX'),('wallets','Guides','Your first Solana wallet: a calmer place to start','Addresses, recovery phrases and your first transaction. A practical introduction to the basics.','Maya Chen','MC'),('community','Culture','Communities are more than a scrolling chat','The small habits that help an online group become a place people want to return to.','Alex Rivera','AX'),('orbital','Ecosystem','A better way to explore the Solana ecosystem','Start with the problem you want to understand, rather than the loudest project in your feed.','Arun Rao','AR')]
(R/'docs/demo-posts.json').write_text(json.dumps(posts,indent=2))
# Static preview: honest representative content, not a fake network or financial dashboard.
nav=''.join(f'<a href="archive.html?topic={t}">{t}</a>' for t in ['Journal','Guides','Builders'])
header=f'<header class="ep-header"><div class="ep-wrap ep-header-inner"><a class="ep-brand" href="index.html">{brand}</a><nav class="ep-nav" aria-label="Main navigation">{nav}<a href="about.html">About</a></nav><div class="ep-tools">{toggle}<details class="ep-mobile"><summary>Menu</summary><nav aria-label="Mobile navigation">{nav}<a href="about.html">About</a></nav></details></div></div></header>'
footer=f'''<footer class="ep-footer"><div class="ep-wrap"><div class="ep-footer-top"><div><a class="ep-brand" href="index.html">{brand}</a><p>An independent space for ideas, explanations and the people behind them.</p></div><nav class="ep-footer-links" aria-label="Footer"><a href="about.html">About the journal</a><a href="archive.html">All stories</a><a href="feed.xml">RSS feed ↗</a></nav></div><div class="ep-footer-bottom"><span>Independent publishing. No wallet connection required.</span><span class="ep-credit">Powered by <a href="https://gonk.fun/" rel="nofollow">gonk.fun</a></span></div></div></footer>'''
search='<form class="ep-search" action="archive.html" method="get" role="search"><label class="ep-sr" for="ep-search">Search articles</label><input id="ep-search" name="q" type="search" placeholder="Find a story…"/><button type="submit" aria-label="Search articles">↗</button></form>'
rail='<aside class="ep-rail" aria-label="Reading list">'+search+notes.replace('GUIDES','archive.html?topic=Guides')+'<section><h2>The reading list</h2><ol class="ep-list">'+''.join(f'<li><div><a href="article.html">{p[2]}</a><small>{p[1]} · Sample article</small></div></li>' for p in posts[:3])+'</ol></section><section><h2>Find your corner</h2><div class="ep-rail-links">'+''.join(f'<a href="archive.html?topic={t}">{t}<span aria-hidden="true">↗</span></a>' for t in topics)+'</div></section><section class="ep-rss"><h2>A feed, at your pace.</h2><p>Follow new posts in your favourite RSS reader. No algorithm deciding what you see.</p><a class="ep-button" href="feed.xml">Follow through RSS ↗</a></section></aside>'
cards=''.join(f'''<article class="ep-card" data-topic="{p[1]}"><a class="ep-card-image" href="article.html" tabindex="-1" aria-hidden="true"><img src="assets/{p[0]}.svg" alt="" width="800" height="600" loading="lazy"/></a><div class="ep-meta"><a class="ep-category" href="archive.html?topic={p[1]}">{p[1]}</a><span>Sample article</span></div><h3><a href="article.html">{p[2]}</a></h3><p>{p[3]}</p><div class="ep-byline"><span class="ep-avatar" aria-hidden="true">{p[5]}</span>{p[4]}<span>· Demo author</span></div></article>''' for p in posts)
strip='<nav class="ep-topics" aria-label="Topics"><span>FIND YOUR SIGNAL</span>'+''.join(f'<a class="ep-chip" href="archive.html?topic={t}">{t}</a>' for t in topics)+'</nav>'
def shell(title,body,extra=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="description" content="Epoch, an original free Solana editorial theme by Gonk Themes."/><title>{title} · Epoch</title><meta name="robots" content="noindex,follow"/><link rel="icon" type="image/svg+xml" href="assets/epoch-favicon.svg"/><link rel="stylesheet" href="assets/epoch.css"/><script src="assets/epoch.js" defer></script></head><body><a class="ep-skip" href="#main">Skip to content</a><div class="ep-demo-note">EPOCH / THEME 01 — Design preview. All articles and authors are fictional examples.</div>{header}{body}{footer}{extra}</body></html>'''
home=f'<div class="ep-wrap">{hero.replace("GUIDES","archive.html?topic=Guides")}{strip}<div class="ep-content-grid"><main id="main" tabindex="-1"><div class="ep-section-heading" id="latest"><h2>The journal<span style="color:var(--ep-accent)">.</span></h2><p>THOUGHTFULLY CURATED</p></div><div class="ep-card-grid">{cards}</div><div class="ep-pagination"><a href="archive.html">Explore all stories ↗</a></div></main>{rail}</div>{banner.replace("SECURITY","archive.html?topic=Security")}</div>'
(R/'preview/index.html').write_text(shell('The next block starts here',home))
archive=f'<div class="ep-wrap"><div class="ep-archive-head"><div class="ep-eyebrow">The full picture</div><h1 id="archive-title">The journal.</h1><p class="ep-lead" id="archive-description">Ideas, explanations and perspectives from across the ecosystem.</p></div>{strip}<div class="ep-content-grid"><main id="main" tabindex="-1"><div class="ep-card-grid" id="results">{cards}</div><div class="ep-empty" id="empty" hidden><h2>No stories found.</h2><p>Try a different word or explore another topic.</p><a class="ep-button secondary" href="archive.html">View all stories</a></div></main>{rail}</div></div>'
archivejs='''<script>const params=new URLSearchParams(location.search),topic=params.get('topic'),q=params.get('q')||'';document.getElementById('archive-title').textContent=topic|| (q?'Search: '+q:'The journal.');let n=0;for(const el of document.querySelectorAll('#results .ep-card')){const show=(!topic||topic==='Journal'||el.dataset.topic===topic)&&(!q||el.textContent.toLowerCase().includes(q.toLowerCase()));el.hidden=!show;if(show)n++;}document.getElementById('empty').hidden=n>0;</script>'''
(R/'preview/archive.html').write_text(shell('Explore the journal',archive,archivejs))
article='''<main class="ep-wrap" id="main" tabindex="-1"><article class="ep-article"><nav class="ep-breadcrumb" aria-label="Breadcrumb"><a href="index.html">Home</a><span aria-hidden="true">/</span><a href="archive.html?topic=Security">Security</a></nav><div class="ep-eyebrow">Security / A practical starting point</div><h1>The wallet check you should make before every connection</h1><p class="ep-article-lead">Permissions are small decisions with real consequences. Here’s how to read them without getting lost.</p><div class="ep-byline ep-meta"><span class="ep-avatar" aria-hidden="true">MC</span>Maya Chen · Fictional demo author · Sample article</div><img class="ep-article-hero" src="assets/security.svg" alt="Abstract layers orbiting a central point" width="800" height="600"/><p class="ep-caption">Original theme artwork. This page demonstrates long-form content styling.</p><details class="ep-toc"><summary>In this article</summary><ol><li><a href="#connection">A connection is a starting point</a></li><li><a href="#read">Read the request</a></li><li><a href="#pause">Make room for a pause</a></li></ol></details><div class="ep-prose"><p>A wallet request should be understandable before it is approved. You don’t need to recognise every line of technical detail, but you should know which site is asking and what you expect the action to do.</p><h2 id="connection">A connection is a starting point.</h2><p>Connecting usually shares your public address. A signature or transaction is a separate request. Check each request on its own terms rather than assuming that an earlier connection makes everything that follows safe.</p><blockquote>The most useful habit is a short pause between a request and an approval.</blockquote><h2 id="read">Read the request, not the countdown.</h2><p>Start with three questions:</p><ol><li>Am I on the domain I intended to visit?</li><li>Does the requested action match what I just clicked?</li><li>Do I understand the permissions and expected changes?</li></ol><table><thead><tr><th>Request</th><th>What to look for</th></tr></thead><tbody><tr><td>Connect</td><td>The requesting site and shared accounts</td></tr><tr><td>Sign a message</td><td>The text, purpose and requesting application</td></tr><tr><td>Approve a transaction</td><td>The actions, permissions, assets and expected changes</td></tr></tbody></table><h2 id="pause">Make room for a pause.</h2><p>If a request is unclear, cancel it and check the application’s official documentation. This sample article is educational content for the theme preview; it does not assess any particular wallet or application.</p><pre><code>Check the domain → Read the request → Decide</code></pre><p>Keep recovery phrases private and store a recovery method securely. A legitimate support conversation should never require your recovery phrase.</p></div><div class="ep-author"><span class="ep-avatar" aria-hidden="true">MC</span><div><strong>Maya Chen</strong><p>Fictional demo author. Replace this profile with your publication’s real author biography.</p></div></div><div class="ep-share"><a href="https://x.com/intent/post?text=Read%20the%20wallet%20request%20before%20approving" target="_blank" rel="noopener noreferrer">Draft on X ↗</a><button data-epoch-copy="" hidden>Copy article link</button></div><a class="ep-text-link" href="archive.html">← Back to the journal</a></article></main>'''
(R/'preview/article.html').write_text(shell('The wallet check',article))
about='''<main class="ep-wrap" id="main" tabindex="-1"><article class="ep-article"><div class="ep-eyebrow">A quieter corner of the ecosystem</div><h1>Built for people.<br/>Open to ideas.</h1><p class="ep-article-lead">Epoch is an independent publication theme for Solana communities, curious readers and the people building what comes next.</p><div class="ep-prose"><h2>Make it yours.</h2><p>This is a sample About page. Introduce your editors, explain your editorial process and tell readers how to get in touch. Replace the demo content with your own work before publishing.</p><h2>A publication, not a trading interface.</h2><p>The theme has no wallet connection, price feed or trading integration. Add links to your community and publish useful stories at your own pace.</p><h2>Open by design.</h2><p>Epoch is free software under GPL-2.0-or-later. Its source, artwork and installation guides are included. The footer credit can be removed without breaking your site.</p></div><a class="ep-button secondary" href="index.html">Explore the journal ↗</a></article></main>'''
(R/'preview/about.html').write_text(shell('About',about))
(R/'preview/404.html').write_text(shell('Page not found','<main class="ep-wrap ep-article" id="main"><div class="ep-eyebrow">404 / Wrong turn</div><h1>This block<br/>is missing.</h1><p class="ep-lead">The page may have moved. Let’s find something worth reading.</p>'+search+'<a class="ep-button" href="index.html">Back to the journal ↗</a></main>'))
(R/'preview/feed.xml').write_text('<?xml version="1.0"?><rss version="2.0"><channel><title>Epoch — design preview</title><link>https://gonk.fun/</link><description>Demo RSS document. Installed themes use the real platform feed.</description></channel></rss>')
# Keep source fragments for both native platforms.
(R/'shared/fragments.json').write_text(json.dumps(dict(hero=hero,notes=notes,banner=banner,toggle=toggle,topics=topics),indent=2))
print('Built original assets and five interactive static preview pages.')
